def links(p,case=True):
 s=f'<a class="text-link" href="https://github.com/akilanpl/{p["repo"]}" target="_blank" rel="noopener">GitHub <span aria-hidden="true">↗</span><span class="sr-only"> — {e(p["name"])}</span></a>'
